/* ---------- Draft review ---------- */
/* what the agent wrote, laid out like the email it is: who it goes to, the subject, the message and what is attached,
   then send now or later, or discard. Before sending it checks for an attachment the message mentions, and after
   sending there is a short window to undo. The warning and the result sit on the head's columns (owner, 18 Nov): their mark
   centred under the head's tile, their words on the title's words, their buttons ending on the content's right edge, their
   tint reaching 8px out round them */
.drf{position:relative;width:100%;max-width:440px;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
/* Soft's card is plush: its content 20px in from every edge (owner, 22 Nov: "more padding inside"); Blueprint and Clean keep
   16px */
.drf.panel{padding:var(--dm-s-5)}
:root:not([data-style="soft"],[data-style="clean"]) .drf.panel:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){padding:var(--dm-s-4)}
.drf-h{display:flex;align-items:center;gap:var(--dm-s-3)}
.drf-ag{width:32px;height:32px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-chip);color:var(--dm-fg2);display:grid;place-items:center;flex:none}
.drf-ht{flex:1;min-width:0;display:flex;flex-direction:column}
.drf-ht b{font-weight:500;font-size:14px}
.drf-ht span{font-size:13px}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.drf :is(.ib,.pill):active{transform:none}
.drf-fs{display:flex;flex-direction:column;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.drf-r{display:flex;align-items:center;gap:10px;min-height:40px;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13.5px}
.drf-l{width:52px;flex:none;color:var(--dm-muted);font-size:13px}
.drf-p{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 10px 0 3px;border-radius:var(--dm-r-pill);background:var(--dm-chip);font-size:13px}
.drf-p .av{width:20px;height:20px;font-size:9px}
.drf-s{flex:1;min-width:0;height:38px;padding:0;border:0;background:none;outline:0;font:inherit;font-size:13.5px;color:var(--dm-fg)}
.drf-r:has(.drf-s:focus){border-bottom-color:color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.drf-b{font-size:14px;line-height:1.6;color:var(--dm-fg);outline:0;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)))}
.drf-b:focus{box-shadow:0 0 0 6px var(--dm-surface),0 0 0 7px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.drf-att{display:flex;flex-wrap:wrap;gap:6px}
.drf-att:empty{display:none}
.drf-file{display:inline-flex;align-items:center;gap:var(--dm-s-2);height:30px;padding:0 10px;border-radius:var(--dm-r-sm);background:var(--dm-chip);font-size:13px}
.drf-file>svg{color:var(--dm-fg2)}
.drf-file .muted{font-size:12px;display:inline-flex;align-items:center}
.drf-file .spin{width:10px;height:10px}
/* the shut warning is hidden once it has folded away, so nothing measures the clipped part as if it were drawn */
.drf-wf.shut>div{visibility:hidden;transition:visibility 0s var(--dm-t)}
/* a warning notice (owner, 18 Nov; Model picker's busy notice is the reference): a faint warning tint, the filled warning sign
   in the warning mark colour, the words in the text colour, the action that settles it in the warning tint (.pill.warn), and
   the other button white beside it */
.drf-w{margin:0 calc(-1 * var(--dm-s-2));padding:var(--dm-s-3) var(--dm-s-2) var(--dm-s-2);border-radius:calc(var(--dm-r-card) - 8px);background:color-mix(in srgb,var(--dm-warn-bg) 45%,transparent);display:grid;grid-template-columns:32px minmax(0,1fr);align-items:start;column-gap:var(--dm-s-3);row-gap:var(--dm-s-2)}
.drf-wi{grid-area:1/1;justify-self:center;width:16px;height:16px;margin-top:2px;overflow:visible}
.drf-wi .a{fill:var(--dm-warn-mark);stroke:var(--dm-warn-mark);stroke-width:2;stroke-linejoin:round}
.drf-wi .b{fill:none;stroke:var(--dm-surface);stroke-width:2.2;stroke-linecap:round}
.drf-w p{grid-area:1/2;margin:0;font-size:13px;line-height:20px;color:var(--dm-fg)}
.drf-wa{grid-area:2/1/3/3;display:flex;justify-content:flex-end;flex-wrap:wrap;gap:var(--dm-s-2)}
.drf-w .pill.ghost{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-on-tint-btn)}
@media (hover:hover) and (pointer:fine){.drf-w .pill.ghost:hover{box-shadow:var(--dm-on-tint-btn-h)}}
/* no room is kept for what comes later (owner, 17 Nov): the card eases to its new height as the attachment, the warning or
   the result arrives (grow()); its menu opens out of it, and nothing changes height while the menu is open */
.drf.growing:has(.drf-pop.open){overflow:visible}
/* a hairline sets the buttons apart from the message, as in a mail composer */
.drf-f{display:flex;align-items:center;gap:var(--dm-s-2);padding-top:var(--dm-s-5);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
:root:not([data-style="soft"],[data-style="clean"]) .drf-f:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){padding-top:var(--dm-s-4)}
.drf-f .sp{flex:1}
.drf-when{font-size:13px}
.drf-mg{display:flex;gap:1px;flex:none}
.drf-go{border-radius:var(--dm-r-pill) 0 0 var(--dm-r-pill);padding-right:var(--dm-s-3)}
.drf-dd{border-radius:0 var(--dm-r-pill) var(--dm-r-pill) 0;padding:0 9px}
.drf-pop{min-width:220px}
.drf.sent .drf-fs,.drf.sent .drf-b,.drf.sent .drf-att{opacity:.55;transition:opacity .32s}
/* the result says what happened, so the head's tag steps aside while it shows (no row repeats what the card says) */
.drf-tag{transition:opacity .32s var(--dm-ease)}
.drf.sent .drf-tag{opacity:0}
/* sent, scheduled or discarded: a neutral row in the footer's place (owner, 18 Nov: a finished state has no green fill), its
   mark in the head tile's column (sent is the green tick) and its words on the title's, with a white button to take it back */
.drf-done{display:flex;align-items:center;gap:var(--dm-s-3);margin:0 -8px;padding:8px;border-radius:calc(var(--dm-r-card) - 8px);background:var(--dm-chip);font-size:13.5px}
.drf-done>.g{width:32px;display:grid;place-items:center;flex:none;color:var(--dm-fg2)}
/* (on the grey row the tick takes the text green, as Permission gate's done row, so it keeps 3:1 on the grey) */
.drf-done:not(.bin,.later)>.g{color:var(--dm-ok)}
.drf-done .t{flex:1;min-width:0;display:flex;flex-direction:column}
.drf-done .t span{font-size:13px}
.drf-done .t .muted{color:var(--dm-fg2)}
.drf-done .pill{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-on-tint-btn)}
@media (hover:hover) and (pointer:fine){.drf-done .pill:hover{box-shadow:var(--dm-on-tint-btn-h)}}
/* Clean (owner, 17 and 18 Nov): its content 16px from each edge; the buttons on the off-white foot strip, 16px from the card's
   edges and the strip's hairline (owner, 23 Nov), and the result in the strip's place, on one line, its mark under the head's tile */
:root[data-style="clean"] .drf.panel,:root [data-style="clean"] .drf.panel,:root [data-style="clean"].drf.panel{padding:16px}
:root[data-style="clean"] :is(.drf-f,.drf-done),:root [data-style="clean"] :is(.drf-f,.drf-done),:root [data-style="clean"]:is(.drf-f,.drf-done){margin:4px -16px -16px;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
/* (on a phone its words can take two lines: the strip grows with them, its mark and button staying on the words' centre line) */
:root[data-style="clean"] .drf-done,:root [data-style="clean"] .drf-done,:root [data-style="clean"].drf-done{padding-left:16px;font-size:12.5px}
:root[data-style="clean"] :is(.drf-done .t span,.drf-when),:root [data-style="clean"] :is(.drf-done .t span,.drf-when),:root [data-style="clean"]:is(.drf-done .t span,.drf-when){font-size:12.5px}
/* (a step of --dm-ok in the vivid green keeps the tick at 3:1 on the off-white strip, as Attachment tray's) */
:root[data-style="clean"] .drf-done:not(.bin,.later)>.g,:root [data-style="clean"] .drf-done:not(.bin,.later)>.g,:root [data-style="clean"].drf-done:not(.bin,.later)>.g{color:color-mix(in srgb,var(--dm-ok-mark) 80%,var(--dm-ok))}
/* (one line of words is a 28px row like the button beside it; two lines, on a phone, sit 16px from the strip's edges as it does) */
:root[data-style="clean"] .drf-done .t,:root [data-style="clean"] .drf-done .t,:root [data-style="clean"].drf-done .t{flex-direction:row;flex-wrap:wrap;align-items:baseline;align-content:center;column-gap:var(--dm-s-2);min-height:28px;line-height:20px}
:root[data-style="clean"] .drf-done .t span,:root [data-style="clean"] .drf-done .t span,:root [data-style="clean"].drf-done .t span{color:var(--dm-muted)}
:root[data-style="clean"] .drf-done .pill,:root [data-style="clean"] .drf-done .pill,:root [data-style="clean"].drf-done .pill{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .drf-done .pill:hover,:root [data-style="clean"] .drf-done .pill:hover,:root [data-style="clean"].drf-done .pill:hover{box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .drf-done .pill:active,:root [data-style="clean"] .drf-done .pill:active,:root [data-style="clean"].drf-done .pill:active{box-shadow:var(--dm-btn2-press)}
:root[data-style="clean"] .drf-w .pill.ghost,:root [data-style="clean"] .drf-w .pill.ghost,:root [data-style="clean"].drf-w .pill.ghost{background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .drf-w .pill.ghost:hover,:root [data-style="clean"] .drf-w .pill.ghost:hover,:root [data-style="clean"].drf-w .pill.ghost:hover{box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .drf-w .pill.ghost:active,:root [data-style="clean"] .drf-w .pill.ghost:active,:root [data-style="clean"].drf-w .pill.ghost:active{box-shadow:var(--dm-btn2-press)}
/* a pressed button never goes blank (owner, 18 Nov): the ink button turns to its disabled look at once, so its dark words never
   sit on a fill that is still fading in */
:root[data-style="clean"] :is(.drf-go,.drf-dd)[disabled],:root [data-style="clean"] :is(.drf-go,.drf-dd)[disabled],:root [data-style="clean"]:is(.drf-go,.drf-dd)[disabled]{transition:none}

DM.def('draft-review', (r, c) => {
  const IC = { spark:I('spark'), clip:I('clip','xs'), send:I('send','xs'), chev:I('chev-d','xs'), chk:I('check','xs'), trash:I('trash','xs'), av:AV('MK','var(--dm-av-l)') };
  r.innerHTML = r.innerHTML.replace(/\{(\w+)\}/g, (m, k) => IC[k] || m);
  const root = $('.drf', r), go = $('.drf-go', r), dd = $('.drf-dd', r), att = $('.drf-att', r), wf = $('.drf-wf', r), when = $('.drf-when', r), f = $('.drf-f', r), tag = $('.drf-tag', r), body = $('.drf-b', r), fields = [$('.drf-fs', r), body, att];
  const items = $$('.drf-pop .mi', r);
  // the card fits what it holds at every moment, easing to it (grow()), once its entrance has ended so it measures the card at
  // its real size; the result row goes into grow()'s wrapper
  Promise.resolve().then(() => Promise.all(root.getAnimations().map(a => a.finished.catch(() => {})))).then(() => { if (!c.dead && root.isConnected) c.offs.push(grow(root)); });
  const into = () => $(':scope>.dm-grow', root) || root;
  let at = 'now', file = false, done = null, run = 0;
  const label = () => (at === 'now' ? I('send','xs') + 'Send' : I('clock','xs') + 'Schedule');
  // a button whose words change is as wide as its words and eases to its new width (owner, 18 Nov)
  const relabel = (b, h) => { const w0 = b.getBoundingClientRect().width; b.innerHTML = h; const w1 = b.getBoundingClientRect().width, cs = getComputedStyle(b);
    if (!REDUCE && w0 && Math.abs(w1 - w0) > .5) b.animate([{ width:w0 + 'px' }, { width:w1 + 'px' }], { duration:(parseFloat(cs.getPropertyValue('--dm-t')) || .34) * 1000, easing:cs.getPropertyValue('--dm-ease').trim() || 'ease' }); };
  // when to send: now, or a set time from the menu beside the button
  items.forEach(m => m.addEventListener('click', () => { at = m.dataset.w; items.forEach(x => x.setAttribute('aria-checked', x === m)); relabel(go, label()); swap(when, at === 'now' ? '' : at); }));
  const warn = on => { wf.classList.toggle('shut', !on); wf.inert = !on; };
  warn(false);
  // the result of sending, scheduling or discarding takes the footer's place, with a white button to take it back
  function row(ic, t, sub, btn, fn, cls){
    f.hidden = true; root.classList.add('sent'); fields.forEach(e => e.inert = true); body.contentEditable = 'false';
    done = html(`<div class="drf-done ${cls || ''}"><span class="g">${ic}</span><span class="t">${t}<span class="muted drf-sub">${sub}</span></span>${btn ? `<button class="pill sm">${btn}</button>` : ''}</div>`);
    into().appendChild(done); enter(done); if (btn) $('button', done).onclick = fn; return done;
  }
  function back(){
    run++; if (done){ done.remove(); done = null; }
    f.hidden = false; root.classList.remove('sent'); fields.forEach(e => e.inert = false); body.contentEditable = 'true';
    go.disabled = dd.disabled = false; relabel(go, label()); swap(tag, 'Not sent'); tag.className = 'tag drf-tag';
  }
  function send(force){
    // the message talks about an attachment that isn't there: say so before it goes
    if (!force && !file && /attach/i.test(body.textContent)){ warn(true); return; }
    warn(false);
    const id = ++run;
    c.run(async () => {
      go.disabled = dd.disabled = true; relabel(go, `<span class="spin"></span>${at === 'now' ? 'Sending' : 'Scheduling'}`);
      await c.wait(900); if (id !== run) return;
      if (at !== 'now'){ row(I('clock'), `Scheduled for ${at.replace(/^\w/, ch => ch.toLowerCase())}`, 'To Maya Kim', 'Cancel', back, 'later'); swap(tag, 'Scheduled'); tag.className = 'tag b drf-tag'; return; }
      // a few seconds to take it back before it really goes
      const d = row(I('ok'), 'Sent to Maya Kim', 'You can undo for 5s', 'Undo', back), sub = $('.drf-sub', d);
      for (let k = 5; k > 0; k--){ sub.textContent = `You can undo for ${k}s`; await c.wait(1000); if (id !== run) return; }
      $('button', d).remove(); swap(sub, 'Delivered just now'); swap(tag, 'Sent'); tag.className = 'tag ok drf-tag';
    });
  }
  go.onclick = () => send(false);
  $('.drf-any', r).onclick = () => send(true);
  $('.drf-at', r).onclick = () => c.run(async () => {
    if (file) return; warn(false);
    const chip = html(`<span class="drf-file">${I('file','xs')}<span>Pricing v4 summary.pdf</span><span class="muted drf-fz"><span class="spin"></span></span></span>`);
    att.appendChild(chip); enter(chip);
    await c.wait(1200); $('.drf-fz', chip).textContent = '240 KB'; file = true;
  });
  $('.drf-x', r).onclick = () => { warn(false); row(I('trash'), 'Draft discarded', 'Nothing was sent', 'Undo', back, 'bin'); };
  // the preview's story: send, get stopped by the missing attachment, attach it, send, and let the undo window pass
  c.story(async s => {
    await s.beat(3);
    await s.point(body, false); await s.beat(3);
    await s.tap(go); s.away();
    await s.until(() => !wf.classList.contains('shut')); await s.beat(5);
    await s.tap($('.drf-at', r)); s.away();
    await s.until(() => file); await s.beat(2);
    await s.tap(go); s.away();
    await s.until(() => done && !$('button', done));
  });
});
